using System;using System.Windows.Forms;using QuanLyHoSoBenhAn.Services;
namespace QuanLyHoSoBenhAn.Forms{public partial class FrmLapToaThuoc:Form{private readonly ToaThuocService service=new ToaThuocService();public FrmLapToaThuoc(){InitializeComponent();}private void NavBenhNhan_Click(object s,EventArgs e){using(var f=new FrmBenhNhan())f.ShowDialog(this);}private void NavKhamBenh_Click(object s,EventArgs e){using(var f=new FrmKhamBenh())f.ShowDialog(this);}private void NavLapToa_Click(object s,EventArgs e){}private void btnThemThuoc_Click(object s,EventArgs e){if(cboThuoc.SelectedIndex>0)dgvThuoc.Rows.Add("T003",cboThuoc.Text,nudSoLuong.Value,txtLieuDung.Text);}private void btnLuuToa_Click(object s,EventArgs e){var r=service.TaoToaThuoc();MessageBox.Show(r.ThongBao,"Thông báo");}private void btnGhiThanhToan_Click(object s,EventArgs e){cboThanhToan.SelectedIndex=1;MessageBox.Show("Đã ghi thanh toán.","Thông báo");}private void btnHoanTat_Click(object s,EventArgs e){cboRaVien.SelectedIndex=1;MessageBox.Show("Đã hoàn tất hồ sơ.","Thông báo");}}}
